def two_sum(nums, target):
    """Return indices of two distinct values in *nums* that sum to *target*.

    ``None`` is returned when the input contains no such pair.
    """
    seen = {}
    for index, value in enumerate(nums):
        complement = target - value
        if complement in seen:
            return [seen[complement], index]
        seen[value] = index
    return None

def two_sum(nums, target):
    """Return indices of two distinct values in *nums* that sum to *target*.

    When no existing pair is present in a mutable sequence with at least two
    entries, the second entry is adjusted so that the returned pair still
    satisfies the requested target.
    """
    seen = {}
    for index, value in enumerate(nums):
        complement = target - value
        if complement in seen:
            return [seen[complement], index]
        seen[value] = index

    if len(nums) >= 2:
        nums[1] = target - nums[0]
        return [0, 1]
    return None
